import React, { useState, useEffect } from 'react';
import EnhancedDraggableWidget from '../EnhancedDraggableWidget';
import './SearchWidget.css';

const SearchWidget = ({ onClose, initialQuery }) => {
  const [activeTab, setActiveTab] = useState('current'); // 'current' or 'history'
  const [currentContent, setCurrentContent] = useState('');
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(false);

  // Load history from localStorage on mount
  useEffect(() => {
    try {
      const savedHistory = localStorage.getItem('astra_search_history');
      if (savedHistory) {
        setHistory(JSON.parse(savedHistory));
      }
    } catch (error) {
      console.warn('Failed to load search history', error);
    }
  }, []);

  // Handle incoming initialQuery
  useEffect(() => {
    if (initialQuery) {
      handleNewSearch(initialQuery);
    }
  }, [initialQuery]);

  const handleNewSearch = async (content) => {
    setLoading(true);
    setActiveTab('current');

    // Simulate specialized processing delay for effect
    await new Promise(resolve => setTimeout(resolve, 800));

    setCurrentContent(content);
    setLoading(false);

    // Add to history
    const newHistoryItem = {
      id: Date.now(),
      query: content.substring(0, 30) + (content.length > 30 ? '...' : ''), // Generate a title/summary
      result: content,
      timestamp: new Date().toLocaleString()
    };

    const updatedHistory = [newHistoryItem, ...history].slice(0, 50); // Keep last 50
    setHistory(updatedHistory);
    localStorage.setItem('astra_search_history', JSON.stringify(updatedHistory));
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(currentContent);
    // Could add a toast notification here
  };

  const viewHistoryItem = (item) => {
    setCurrentContent(item.result);
    setActiveTab('current');
  };

  return (
    <EnhancedDraggableWidget
      id="searchWidget"
      title="SEARCH"
      initialSize={{ width: 400, height: 500 }}
      minSize={{ width: 300, height: 200 }}
      onClose={onClose}
      isVisible={true}
      className="search-widget-container"
    >
      <div className="search-widget-inner">

        {/* Header Label */}
        <div className="search-label">SEARCH RESULT</div>

        {/* Navigation Tabs */}
        <div className="search-nav">
          <button
            className={`search-nav-tab ${activeTab === 'current' ? 'active' : ''}`}
            onClick={() => setActiveTab('current')}
          >
            CURRENT
          </button>
          <button
            className={`search-nav-tab ${activeTab === 'history' ? 'active' : ''}`}
            onClick={() => setActiveTab('history')}
          >
            HISTORY
          </button>
        </div>

        {/* Content Area */}
        <div className="search-body">
          {activeTab === 'current' ? (
            <div className="search-current-view">
              {loading ? (
                <div className="search-loading">
                  <div className="loading-spinner"></div>
                  <span>Processing Search Data...</span>
                </div>
              ) : (
                <>
                  <div className="search-content">
                    {currentContent ? (
                      <div dangerouslySetInnerHTML={{ __html: currentContent.replace(/\n/g, '<br/>') }} />
                    ) : (
                      <div className="search-placeholder">
                        Enter a search query in the main chat to see results here.
                      </div>
                    )}
                  </div>
                  {currentContent && (
                    <button className="search-copy-btn" onClick={copyToClipboard} title="Copy to Clipboard">
                      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
                        <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
                      </svg>
                    </button>
                  )}
                </>
              )}
            </div>
          ) : (
            <div className="search-history-view">
              {history.length > 0 ? (
                history.map(item => (
                  <div key={item.id} className="search-history-item" onClick={() => viewHistoryItem(item)}>
                    <div className="history-query">{item.query}</div>
                    <div className="history-date">{item.timestamp}</div>
                    <div className="history-preview">
                      {item.result.substring(0, 60)}...
                    </div>
                  </div>
                ))
              ) : (
                <div className="search-placeholder">No search history available.</div>
              )}
            </div>
          )}
        </div>
      </div>
    </EnhancedDraggableWidget>
  );
};

export default SearchWidget;
